import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def rects_of(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; comp=[(i,j)]; c=g[i][j]
                while stack:
                    a,b=stack.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; stack.append((x,y)); comp.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                out.append((min(rs),min(cs),max(rs),max(cs),c))
    return out

def fill_interiors(g):
    bg=g[0][0]; g=[row[:] for row in g]
    for i,j,i2,j2,c in rects_of(g,bg):
        f=2 if (i2-i-1)%2==0 and (j2-j-1)%2==0 else 7
        for a in range(i+1,i2):
            for b in range(j+1,j2): g[a][b]=f
    return g

print(fill_interiors(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(fill_interiors(G['Demo pair 2 input'])==G['Demo pair 2 output'])
print(json.dumps(fill_interiors(G['Test input'])))

